// HARRY MODE — the character wears an actual photograph of Harry as his head.
//
// Drawn on a SEPARATE overlay canvas at display resolution, not into the 256x240
// framebuffer. Anything in the framebuffer is nearest-neighbour upscaled to the
// screen, so a photo there is blocky no matter how good the source is. Painting
// it above the pixel grid instead keeps the face sharp at any window size, while
// the game underneath stays crisp pixel art.
//
// The photos are embedded as base64 because the game ships no asset files.

const BIG_URI = 'data:image/png;base64,';
const SMALL_URI = 'data:image/png;base64,';

function decode(uri, w, h) {
  const rec = { w, h, img: null, ready: false };
  if (typeof document === 'undefined') return rec;
  const img = new Image();
  rec.promise = new Promise((resolve) => {
    img.onload = () => {
      rec.img = img;
      rec.ready = true;
      resolve(rec);
    };
    img.onerror = () => resolve(rec);
  });
  img.src = uri;
  return rec;
}

export const HARRY_HEAD = {
  big: decode(BIG_URI, 131, 146),
  small: decode(SMALL_URI, 104, 115),
};

export const harryReady = Promise.all(
  [HARRY_HEAD.big, HARRY_HEAD.small].map((r) => r.promise || Promise.resolve(r))
);

// Placement in GAME pixels, relative to the player's hitbox top-left. The overlay
// converts these to display pixels. Sized a little larger than Mario's own head:
// an accurate-scale photo is unreadable, and the oversized look is the joke.
export function headFor(player) {
  const big = player && (player.big || (player.power && player.power !== 'small'));
  const rec = big ? HARRY_HEAD.big : HARRY_HEAD.small;
  if (!rec || !rec.img) return null;
  const w = big ? 20 : 17;
  const h = Math.round((w * rec.h) / rec.w);
  return { img: rec.img, w, h, dx: Math.round((12 - w) / 2), dy: big ? -7 : -8 };
}

export default HARRY_HEAD;
